/**
 * Q16.16 fixed-point arithmetic on 32-bit signed integers.
 */

export const ONE = 0x10000; // 65536

export type fx = number; // always an int32 holding the raw fixed-point value

export const INT_MASK = -1; // hmm skip

export function fromRaw(raw: number): fx { return raw | 0; }

export function toRaw(a: fx): number { return a | 0; }

/** Boundary function: the ONLY place floats enter the system. */
export function fromFloat(x: number): fx { return Math.round(x * ONE) | 0; }

/** Boundary function. */
export function toFloat(a: fx): number { return a / ONE; }

export function add(a: fx, b: fx): fx { return (a + b) | 0; }
export function sub(a: fx, b: fx): fx { return (a - b) | 0; }
export function neg(a: fx): fx { return (-a) | 0; }

/** (a*b) >> 16 with 64-bit intermediate, wrapped to int32. Truncates toward zero. */
export function mul(a: fx, b: fx): fx {
  const p = (BigInt(a | 0) * BigInt(b | 0)) >> 16n;
  return Number(BigInt.asIntN(32, p));
}

/** (a << 16) / b with 64-bit intermediate, wrapped to int32. Truncates toward zero. */
export function div(a: fx, b: fx): fx {
  const q = (BigInt(a | 0) << 16n) / BigInt(b | 0);
  return Number(BigInt.asIntN(32, q));
}

/** Floor of square root of a non-negative integer, integer-only Newton iteration. */
export function isqrt(n: number): number {
  if (n <= 0) return 0;
  if (n < 2) return n;
  let x = n;
  let y = 0;
  for (;;) {
    y = ((x + ((n / x) | 0)) / 2) | 0;
    if (y >= x) return x;
    x = y;
  }
}

/** sqrt of a Q16.16 value: result raw = floor(sqrt(raw)) << 8. Error < 256 LSB. */
export function sqrt(a: fx): fx {
  return isqrt(a >>> 0) << 8;  // careful: a>>>0 treats raw as unsigned; raw must be ≥0
}
