export function fnv1a(data: Uint8Array): number {
  let h = 0x811c9dc5 | 0;
  for (let i = 0; i < data.length; i++) {
    h ^= data[i] & 0xff;
    h = Math.imul(h, 0x01000193);
  }
  return h >>> 0;
}

