export const ONE = 0x10000; // 65536 == fixed-point 1.0

/** Raw Q16.16 value, always an int32. */
export type fx = number;

export function fromRaw(raw: number): fx {
  return raw | 0;
}

export function toRaw(a: fx): number {
  return a | 0;
}

/**
 * Float -> fixed boundary. Rounds to nearest (ties toward +inf by the +0.5/-0.5
 * asymmetry), implemented without Math.round so the module stays Math-free.
 */
export function fromFloat(x: number): fx {
  return (x >= 0 ? x * ONE + 0.5 : x * ONE - 0.5) | 0;
}

/** Fixed -> float boundary. Exact: one LSB is exactly 1/65536. */
export function toFloat(a: fx): number {
  return a / ONE;
}

/** Wrapping add on int32. */
export function add(a: fx, b: fx): fx {
  return (a + b) | 0;
}

/** Wrapping sub on int32. */
export function sub(a: fx, b: fx): fx {
  return (a - b) | 0;
}

export function neg(a: fx): fx {
  return (-a) | 0;
}

/**
 * (a * b) >> 16 with a full-precision 64-bit intermediate (BigInt),
 * wrapped back to int32. Truncates toward zero, like C fixed-point.
 */
export function mul(a: fx, b: fx): fx {
  const p = (BigInt(a | 0) * BigInt(b | 0)) >> 16n;
  return Number(BigInt.asIntN(32, p));
}

/**
 * (a << 16) / b with a full-precision 64-bit intermediate (BigInt),
 * wrapped back to int32. Truncates toward zero. b must be nonzero.
 */
export function div(a: fx, b: fx): fx {
  if (b === 0) throw new Error('fixed.div: division by zero');
  const q = (BigInt(a | 0) << 16n) / BigInt(b | 0);
  return Number(BigInt.asIntN(32, q));
}

/**
 * floor(sqrt(n)) for non-negative integers up to 2^31-1, using integer-only
 * Newton iteration (x' = (x + n/x) / 2). No floats, no Math.sqrt.
 */
export function isqrt(n: number): number {
  if (n <= 1) return n < 0 ? 0 : n;
  let x = n;
  let y = 0;
  for (;;) {
    y = ((x + ((n / x) | 0)) / 2) | 0;
    if (y >= x) return x;
    x = y;
  }
}

