/** Timestep: 1/128 time units. Raw = 65536/128. */
const DT: fx = 512;

/** Gravitational constant G = 1.0. */
const G: fx = ONE;

/** Softening epsilon^2 = 0.25, keeps d2 > 0 and bounds the acceleration. */
const EPS2: fx = 16384; // 0.25 * 65536

export function initialBodies(): Body[] {
  return [
    { m: fromFloat(10), x: fromFloat(-4), y: fromFloat(-1), vx: fromFloat(0.02), vy: fromFloat(0.03) },
    { m: fromFloat(8), x: fromFloat(5), y: fromFloat(0), vx: fromFloat(-0.01), vy: fromFloat(-0.04) },
    { m: fromFloat(6), x: fromFloat(0), y: fromFloat(6), vx: fromFloat(0.015), vy: fromFloat(-0.02) },
  ];
}

/**
 * One semi-implicit (symplectic) Euler step, in place.
 * a_i = sum_{j!=i} G * m_j * (r_j - r_i) / (|r_j - r_i|^2 + eps^2)^{3/2}
 */
export function step(bodies: Body[]): void {
  const n = bodies.length;
  const ax: fx[] = new Array(n).fill(0);
  const ay: fx[] = new Array(n).fill(0);

  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      const bi = bodies[i];
      const bj = bodies[j];
      const dx = sub(bj.x, bi.x);
      const dy = sub(bj.y, bi.y);
      const d2 = add(add(mul(dx, dx), mul(dy, dy)), EPS2);
      const d = sqrt(d2);
