import { initialBodies, step, stateWords } from './sim.js';

const FNV_OFFSET = 0x811c9dc5 | 0;
const FNV_PRIME = 0x01000193 | 0;

export class Fnv1a {
  private h = FNV_OFFSET;

  update(bytes: Uint8Array): this {
    let h = this.h;
    for (let i = 0; i < bytes.length; i++) {
      h ^= bytes[i] & 0xff;
      h = Math.imul(h, FNV_PRIME);
    }
    this.h = h;
    return this;
  }

  /** Hash a list of int32 words as little-endian bytes. */
  updateWords(words: readonly number[]): this {
    const buf = new Uint8Array(words.length * 4);
    for (let i = 0; i < words.length; i++) {
      const w = words[i] | 0;
      buf[i * 4] = w & 0xff;
      buf[i * 4 + 1] = (w >>> 8) & 0xff;
      buf[i * 4 + 2] = (w >>> 16) & 0xff;
      buf[i * 4 + 3] = (w >>> 24) & 0xff;
    }
    return this.update(buf);
  }

  digest(): number {
    return this.h >>> 0;
  }
}

export function fnv1a(data: Uint8Array): number {
  return new Fnv1a().update(data).digest();
}

/**
 * Step the sim `ticks` times from the canonical initial state,
 * feeding every tick's raw int32 state into a streaming FNV-1a.
